            self.examples.append(restored)
        self.lessons = []
        for l in data.get("lessons", []):
            self.lessons.append({
                "text": l["text"],
                "tokens": frozenset(l.get("tokens", [])),
                "source_preview": l.get("source_preview", ""),
            })
        self._pending_errors = data.get("pending_errors", [])


